#!/usr/bin/env python3
"""Build the keep and remove lists for the cleaning of the landed batches' scratch.

Candidates: every tracked file under explorations/compile-ladder/ and under
explorations/reviews/batch-*-review/, less the automatic keeps (every .md; every
gate/ folder; gate-baseline/; baseline-2026-09-19/).
Citers: every tracked text file that is not a removal candidate; iterated, since
a kept candidate's own citations keep what they name.
A citation is a path-like token resolved (a) from the repository root, (b) from
the citing file's folder and each of its ancestors, (c) anchored on a known
folder name (compile-ladder, reviews, rung*, climb-batch-*, plan-*, repair-*,
batch-*-review, ...). A token naming a directory keeps every file under it,
except the candidate roots themselves (explorations/compile-ladder, and each
rung, batch, plan or repair folder directly under it, and each
batch-*-review folder): those are recorded as folder-level citations.
"""
import fnmatch, json, os, posixpath, re, subprocess, sys
from collections import defaultdict

ROOT = '/home/user/fortress'
OUT = os.path.dirname(os.path.abspath(__file__))
os.chdir(ROOT)

tracked = subprocess.run(['git', 'ls-files', '-z'], capture_output=True, check=True).stdout.decode().split('\0')
tracked = [t for t in tracked if t]
tracked_set = set(tracked)

CL = 'explorations/compile-ladder/'
RV = 'explorations/reviews/'
review_dir_re = re.compile(r'^explorations/reviews/batch-[^/]+-review/')

def in_scope(p):
    return p.startswith(CL) or bool(review_dir_re.match(p))

scope = [p for p in tracked if in_scope(p)]
scope_set = set(scope)

def auto_keep_reason(p):
    if p.endswith('.md'):
        return 'report or written note (.md)'
    rel = p[len(CL):] if p.startswith(CL) else None
    if rel is not None:
        if rel.startswith('gate-baseline/'):
            return 'gate baseline'
        if rel.startswith('baseline-2026-09-19/'):
            return 'ladder baseline (the ladder stage reads its raw/)'
        if '/gate/' in '/' + rel:
            return "a gate's tables"
    return None

auto = {p: auto_keep_reason(p) for p in scope}
auto = {p: r for p, r in auto.items() if r}

# Directory index for scope files.
dirs = defaultdict(list)
for p in scope:
    d = posixpath.dirname(p)
    while d and d != 'explorations':
        dirs[d].append(p)
        d = posixpath.dirname(d)

def candidate_root(d):
    """Directories whose citation does not expand to every file under them."""
    if d in ('explorations', 'explorations/compile-ladder', 'explorations/reviews'):
        return True
    if d.startswith(CL):
        rel = d[len(CL):]
        if '/' not in rel and re.match(r'^(rung|climb-batch-|plan-|repair-)', rel):
            return True
    if re.match(r'^explorations/reviews/batch-[^/]+-review$', d):
        return True
    return False

TEXT_EXT = ('.md', '.js', '.py', '.sh', '.txt', '.tex', '.fss', '.fsi', '.test',
            '.tsv', '.json', '.jsonl', '.xml', '.awk', '.el', '.html', '.patch', '.diff',
            '.yml', '.yaml', '.java', '.scala', '.tick', '.csv', '.log', '.out', '.run',
            '.compile', '.compiled', '.walk', '.after', '.before', '.skeptic')

def is_text(p):
    return p.endswith(TEXT_EXT) or '.' not in posixpath.basename(p)

TOKEN = re.compile(r'[A-Za-z0-9_.\-/*?+@${}~\[\]]+')
ANCHOR_CL = re.compile(r'^(rung[^/]*|climb-batch-[^/]+|plan-[^/]+|repair-[^/]+|baseline-2026-09-19|gate-baseline|after|raw)$')
ANCHOR_RV = re.compile(r'^batch-[^/]+-review$')

def clean(tok):
    tok = tok.strip('.,;:)(\'"`*[]{}')
    tok = re.sub(r'#.*$', '', tok)
    tok = re.sub(r'\$\{[^}]*\}', '*', tok)
    tok = re.sub(r'\$[A-Za-z_][A-Za-z0-9_]*', '*', tok)
    tok = re.sub(r'(:\d+([-,]\d+)*)+$', '', tok)
    tok = tok.rstrip('.,;:')
    return tok

def resolutions(tok, citer):
    """Yield candidate repository paths the token may name."""
    out = []
    if not tok or tok in ('.', '..', '/'):
        return out
    i = tok.find('explorations/')
    if i >= 0:
        out.append(tok[i:])
        return out
    if tok.startswith('/'):
        return out
    t = tok[2:] if tok.startswith('./') else tok
    first = t.split('/', 1)[0]
    if first == 'compile-ladder' or first == 'reviews':
        out.append('explorations/' + t)
    elif ANCHOR_CL.match(first) and '/' in t:
        out.append(CL + t)
    elif ANCHOR_RV.match(first) and '/' in t:
        out.append(RV + t)
    # Relative to the citing file's folder and its ancestors (inside the scope trees
    # only for ancestors; the folder itself anywhere).
    d = posixpath.dirname(citer)
    first_d = True
    while d:
        if first_d or d.startswith(CL) or d.startswith(RV):
            out.append(posixpath.normpath(posixpath.join(d, t)))
        first_d = False
        if d in ('explorations/compile-ladder', 'explorations/reviews'):
            break
        d = posixpath.dirname(d)
    return out

folder_level = defaultdict(set)   # candidate root dir -> citers

def cited_by(citer, text):
    hits = {}
    for m in TOKEN.finditer(text):
        raw = m.group(0)
        if '/' not in raw and '.' not in raw:
            continue
        tok = clean(raw)
        if not tok:
            continue
        for r in resolutions(tok, citer):
            r = r.rstrip('/')
            if not r or r.startswith('..'):
                continue
            if any(c in r for c in '*?['):
                pat = r
                for p in scope:
                    if fnmatch.fnmatchcase(p, pat) or fnmatch.fnmatchcase(p, pat + '/*'):
                        hits.setdefault(p, raw)
                continue
            if r in scope_set:
                hits.setdefault(r, raw)
            elif r in dirs:
                if candidate_root(r):
                    folder_level[r].add(citer)
                else:
                    for p in dirs[r]:
                        hits.setdefault(p, raw)
    return hits

def read(p):
    try:
        with open(p, 'rb') as f:
            b = f.read()
    except OSError:
        return ''
    if b'\0' in b[:4096]:
        return ''
    return b.decode('utf-8', 'replace')

# Pre-filter for citers outside the scope: only files that mention something that can
# resolve into the scope.
KEYS = ('compile-ladder', 'batch-', 'rung', 'plan-', 'repair-', 'baseline-2026-09-19',
        'gate-baseline', 'after/', 'raw/', 'explorations/')

citations = defaultdict(dict)   # cited file -> {citer: token}

def scan(citer, force=False):
    text = read(citer)
    if not text:
        return {}
    if not force and not any(k in text for k in KEYS) and not in_scope(citer):
        return {}
    hits = cited_by(citer, text)
    for p, tok in hits.items():
        if p != citer:
            citations[p][citer] = tok
    return hits

outside = [p for p in tracked if not in_scope(p) and is_text(p) and os.path.isfile(p)]
for p in outside:
    scan(p)

kept = set(auto)
frontier = [p for p in auto if is_text(p)]
# Files cited by citers outside the scope
for p in list(citations):
    if p not in kept:
        kept.add(p)
        if is_text(p):
            frontier.append(p)
scanned = set()
rounds = 0
while frontier:
    rounds += 1
    nxt = []
    for c in frontier:
        if c in scanned:
            continue
        scanned.add(c)
        for p in scan(c, force=True):
            if p not in kept:
                kept.add(p)
                if is_text(p):
                    nxt.append(p)
    frontier = nxt

remove = sorted(p for p in scope if p not in kept)
json.dump({
    'kept': sorted(kept),
    'remove': remove,
    'auto': auto,
    'citations': {p: citations[p] for p in sorted(kept) if p in citations},
    'folder_level': {d: sorted(v) for d, v in folder_level.items()},
    'rounds': rounds,
}, open(os.path.join(OUT, 'cited.json'), 'w'), indent=1)
print('scope', len(scope), 'auto', len(auto), 'kept', len(kept), 'remove', len(remove), 'rounds', rounds)

